# A modify or a translation is polled at once, then after 1 s, 2 s, 4 s, ... at most 15 s apart, for at most POLL_WAIT_SECONDS.
POLL_FIRST_SECONDS = 1.0
POLL_MAX_SECONDS = 15.0
POLL_WAIT_SECONDS = 180.0


def poll_delays():
    """The sleeps between two polls: 1, 2, 4, 8, 15, 15, ... until their sum reaches POLL_WAIT_SECONDS."""
    delays, waited, delay = [], 0.0, POLL_FIRST_SECONDS
    while waited < POLL_WAIT_SECONDS:
        step = min(delay, POLL_MAX_SECONDS, POLL_WAIT_SECONDS - waited)
        delays.append(step)
        waited += step
        delay *= 2
    return tuple(delays)


POLL_DELAYS = poll_delays()
MAX_POLLS = len(POLL_DELAYS) + 1  # the poll at once and one after each sleep
# The most API calls one drawing design can spend, the budget it needs before it starts: the largest fixed call count of
# D13a to D18a in the mock when the views list does not name the views (D15a and D16a: 40 calls, with the extra DRAWING_JSON
# export that reads them; 37 without), each of its 8 polled requests (4 modifies, 4 exports) polled MAX_POLLS - 1 = 15 more
# times, plus the 2 calls that delete the drawing and its Part Studio when it fails at the last step:
# 40 + 8 * 15 + 2 = 162. A test recomputes this from the mock.
